import React from 'react';
import { graphql, Link } from 'gatsby';

import Header from '../components/header';
import Layout from '../components/layout';
import SEO from '../components/seo';

const classes = {
  wrapper: 'mt-12',
  title: 'text-3xl text-retroPink font-bold',
  body: 'mt-4 text-gray-200',
  link: 'underline hover:text-retroGold',
};

const NotFoundPage = ({ data }) => (
  <Layout>
    <Header metadata={data.site.siteMetadata} noBlog />
    <div className={classes.wrapper}>
      <h1 className={classes.title}>404: Not Found</h1>
      <p className={classes.body}>
        You just hit a route that doesn&apos;t exist.{' '}
        <Link className={classes.link} to="/">
          Return to safety
        </Link>
        .
      </p>
    </div>
  </Layout>
);

export default NotFoundPage;

export const Head = ({ location }) => (
  <SEO
    title="Not found"
    pathname={location.pathname}
    meta={[{ name: 'robots', content: 'noindex' }]}
  />
);

export const pageQuery = graphql`
  query {
    site {
      siteMetadata {
        name
        title
        description
        author
        github
        linkedin
      }
    }
  }
`;
